use memmap2::{Mmap, MmapMut};
use std::ffi::{OsStr, OsString};
use std::fs::{File, OpenOptions};

#[cfg(unix)]
use std::os::unix::fs::OpenOptionsExt;

use crate::instance::InstanceVersion;
use crate::synchronizer::SynchronizerError;
use crate::synchronizer::SynchronizerError::*;
use crate::utils;

/// Data container stores memory mapped data files allowing
/// to switch between them when data instance version is changed
pub(crate) struct DataContainer {
    /// Base data path
    path_prefix: OsString,
    /// Reader's current local instance version
    version: Option<InstanceVersion>,
    /// Read-only memory mapped files storing data
    read_mmaps: [Option<Mmap>; 2],
    /// Write-only memory mapped files storing data
    write_mmaps: [Option<MmapMut>; 2],
}

impl DataContainer {
    /// Create new instance of `DataContainer`
    pub(crate) fn new(path_prefix: &OsStr) -> Self {
        DataContainer {
            path_prefix: path_prefix.into(),
            version: None,
            read_mmaps: [None, None],
            write_mmaps: [None, None],
        }
    }

    /// Write `data` into mapped data file with given `version`
    pub(crate) fn write(
        &mut self,
        data: &[u8],
        version: InstanceVersion,
    ) -> Result<usize, SynchronizerError> {
        let mmap = &mut self.write_mmaps[version.idx()];
        let data_size = version.size();

        // only open and mmap data file in the following cases:
        // * if it never was opened/mapped before
        // * if current mmap size is smaller than requested data size
        if mmap.is_none() || mmap.as_ref().unwrap().len() < data_size {
            let mut opts = OpenOptions::new();
            opts.read(true).write(true).create(true);

            // Only add mode on Unix-based systems
            #[cfg(unix)]
            opts.mode(0o640);

            let data_file = opts
                .open(version.path(&self.path_prefix))
                .map_err(FailedDataWrite)?;

            // grow data file when its current length exceeded
            let data_len = data.len() as u64;
            if data_len > data_file.metadata().map_err(FailedDataWrite)?.len() {
                utils::set_len(&data_file, data_len as i64).map_err(FailedDataWrite)?;
            }

            *mmap = Some(unsafe { MmapMut::map_mut(&data_file).map_err(FailedDataWrite)? });
        }

        if let Some(mmap) = mmap {
            // copy data to mapped file and ensure it's been flushed
            mmap[..data.len()].copy_from_slice(data);
            mmap.flush().map_err(FailedDataWrite)?;
        }

        Ok(data.len())
    }

    /// Fetch data from mapped data file of given `version`
    #[inline]
    pub(crate) fn data(
        &mut self,
        version: InstanceVersion,
    ) -> Result<(&[u8], bool), SynchronizerError> {
        let mmap = &mut self.read_mmaps[version.idx()];
        let data_size = version.size();

        // only open and mmap data file in the following cases:
        // * if it never was opened/mapped before
        // * if current mmap size is smaller than requested data size
        if mmap.is_none() || mmap.as_ref().unwrap().len() < data_size {
            let data_file = File::open(version.path(&self.path_prefix)).map_err(FailedDataRead)?;
            if data_file.metadata().map_err(FailedDataRead)?.len() < data_size as u64 {
                return Err(FailedEntityRead);
            }
            *mmap = Some(unsafe { Mmap::map(&data_file).map_err(FailedDataRead)? });
        }

        let data = &mmap.as_ref().unwrap()[..data_size];
        let new_version = Some(version);
        let switched = new_version != self.version;
        self.version = new_version;

        Ok((data, switched))
    }
}

use std::fs::File;
use std::io;
#[cfg(target_os = "linux")]
use std::os::fd::AsRawFd;

/// Set the length of the file to the specified length.
pub(crate) fn set_len(file: &File, len: i64) -> Result<(), io::Error> {
    // On Linux platforms, `.set_len()` may not return an error of the disk is full, so we allocate
    // the entire file to ensure space is available.
    #[cfg(target_os = "linux")]
    match unsafe { libc::posix_fallocate(file.as_raw_fd(), 0, len) } {
        0 => Ok(()),
        err => Err(io::Error::from_raw_os_error(err)),
    }
    // Support for non-Linux platforms is best-effort.
    #[cfg(not(target_os = "linux"))]
    file.set_len(len as u64)
}

#![cfg_attr(docsrs, feature(doc_cfg))]
//! `mmap-sync` is a high-performance, concurrent data access library for Rust. It is designed to handle data access between a single writer process and multiple reader processes efficiently using memory-mapped files, wait-free synchronization, and zero-copy deserialization.
//!
//! ## Features
//!
//! - **Memory-mapped files**: This allows different processes to access the same memory space, bypassing the need for costly serialization and deserialization. As a result, `mmap-sync` provides fast, low-overhead data sharing between processes.
//!
//! - **Wait-free synchronization**: Inspired by [Linux kernel's Read-Copy-Update (RCU) pattern](https://www.kernel.org/doc/html/next/RCU/whatisRCU.html) and the [Left-Right concurrency control technique](https://github.com/pramalhe/ConcurrencyFreaks/blob/master/papers/left-right-2014.pdf). Write access to the data is managed by a single writer, with multiple readers able to access the data concurrently.
//!
//! - **Zero-copy deserialization**: Leveraging the [rkyv](https://rkyv.org/) library, `mmap-sync` achieves efficient data storage and retrieval. The templated type `T` for `Synchronizer` can be any Rust struct implementing specified `rkyv` traits.
//!
//! To get started with `mmap-sync`, please see the [examples](https://github.com/cloudflare/mmap-sync/tree/main/examples) provided.
mod data;
pub mod guard;
pub mod instance;
pub mod locks;
mod state;
pub mod synchronizer;
mod utils;

//! Lock strategies.
//!
//! # Safety
//! This crate requires that only one writer be active at a time. It is the caller's responsibility
//! to uphold th is guarantee.
//!
//! Note: if multiple writers are active, it is the caller's responsibility to ensure that each
//! writer is configured with an appropriate lock strategy. For example, mixing the `LockDisabled`
//! strategy with any other strategy is incorrect because it disables lock checks from one of the
//! synchronizers.

#[cfg(unix)]
use std::os::fd::AsRawFd;
use std::{
    fs::File,
    ops::{Deref, DerefMut},
};

use memmap2::MmapMut;

use crate::synchronizer::SynchronizerError;

/// The write lock strategy supports different lock implementations which can be chosen based on
/// the guarantees required, platform support, and performance constraints.
///
/// Note: the lock implementations are sealed to avoid committing to a specific lock interface.
#[allow(private_bounds)]
pub trait WriteLockStrategy<'a>: WriteLockStrategySealed<'a> {}

/// Sealed trait i
pub(crate) trait WriteLockStrategySealed<'a> {
    type Guard: DerefMut<Target = MmapMut> + 'a;

    /// Create a new instance of this lock strategy.
    ///
    /// The `mmap` parameter will have write access controlled by the lock.
    ///
    /// The `file` parameter is required because lock strategies depending on `flock` must hold
    /// the file descriptor open so the kernel does not release the lock.
    fn new(mmap: MmapMut, file: File) -> Self;

    /// Provide read access to mmaped memory.
    fn read(&'a self) -> &'a [u8];

    /// Acquire the lock as specified by the lock strategy.
    ///
    /// On success, return a lock guard which can be used to access the underlying mmaped memory
    /// via [`Deref`]/[`DerefMut`].
    fn lock(&'a mut self) -> Result<Self::Guard, SynchronizerError>;
}

/// Lock protection is disabled.
///
/// # Safety
/// Callers must ensure that there is only a single active writer. For example, the caller might
/// ensure that only one process attempts to write to the synchronizer, and ensure that multiple
/// instances of the process are not spawned.
pub struct LockDisabled(MmapMut);

impl<'a> WriteLockStrategySealed<'a> for LockDisabled {
    type Guard = DisabledGuard<'a>;

    #[inline]
    fn new(mmap: MmapMut, _file: File) -> Self {
        // No need to hold the file descriptor because lock functionality is disabled.
        Self(mmap)
    }

    #[inline]
    fn read(&'a self) -> &'a [u8] {
        &self.0
    }

    #[inline]
    fn lock(&'a mut self) -> Result<Self::Guard, SynchronizerError> {
        Ok(DisabledGuard(&mut self.0))
    }
}

impl WriteLockStrategy<'_> for LockDisabled {}

pub struct DisabledGuard<'a>(&'a mut MmapMut);

impl Deref for DisabledGuard<'_> {
    type Target = MmapMut;

    fn deref(&self) -> &Self::Target {
        &*self.0
    }
}

impl DerefMut for DisabledGuard<'_> {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut *self.0
    }
}

/// Acquire the lock. Once acquired, hold the lock until dropped.
///
/// The `flock` API holds the lock as long as the file descriptor is open, and closes the lock
/// when the descriptor is closed. The descriptor is automatically closed when `File` is dropped.
#[cfg(unix)]
pub struct SingleWriter {
    mmap: MmapMut,
    file: File,
    locked: bool,
}

#[cfg(unix)]
impl<'a> WriteLockStrategySealed<'a> for SingleWriter {
    type Guard = SingleWriterGuard<'a>;

    #[inline]
    fn new(mmap: MmapMut, file: File) -> Self {
        Self {
            mmap,
            file,
            locked: false,
        }
    }

    #[inline]
    fn read(&'a self) -> &'a [u8] {
        &self.mmap
    }

    #[inline]
    fn lock(&'a mut self) -> Result<Self::Guard, SynchronizerError> {
        // We already hold the lock, so return success.
        if self.locked {
            return Ok(SingleWriterGuard(&mut self.mmap));
        }

        // Acquire the lock for the first time.
        // Note: the file descriptor must remain open to hold the lock.
        match unsafe { libc::flock(self.file.as_raw_fd(), libc::LOCK_EX | libc::LOCK_NB) } {
            0 => {
                // Hold the lock until this structure is dropped.
                self.locked = true;
                Ok(SingleWriterGuard(&mut self.mmap))
            }
            _ => Err(SynchronizerError::WriteLockConflict),
        }
    }
}

#[cfg(unix)]
impl WriteLockStrategy<'_> for SingleWriter {}

/// A simple guard which does not release the lock upon being dropped.
#[cfg(unix)]
pub struct SingleWriterGuard<'a>(&'a mut MmapMut);

#[cfg(unix)]
impl Deref for SingleWriterGuard<'_> {
    type Target = MmapMut;

    fn deref(&self) -> &Self::Target {
        &*self.0
    }
}

#[cfg(unix)]
impl DerefMut for SingleWriterGuard<'_> {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut *self.0
    }
}

use std::ffi::{OsStr, OsString};

use crate::synchronizer::SynchronizerError;
use crate::synchronizer::SynchronizerError::*;

/// `InstanceVersion` represents data instance and consists of the following components:
/// - data idx (0 or 1)   - 1 bit
/// - data size (<549 GB) - 39 bits
/// - data checksum       - 24 bits
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct InstanceVersion(pub(crate) u64);

const DATA_SIZE_BITS: usize = 39;
const DATA_CHECKSUM_BITS: usize = 24;

impl InstanceVersion {
    /// Create new `InstanceVersion` from data instance `idx`, `size` and `checksum`
    #[inline]
    pub(crate) fn new(
        idx: usize,
        size: usize,
        checksum: u64,
    ) -> Result<InstanceVersion, SynchronizerError> {
        let mut res: u64 = 0;

        if idx > 1 || size >= 1 << DATA_SIZE_BITS {
            return Err(InvalidInstanceVersionParams);
        }

        res |= (idx as u64) & 1;
        res |= ((size as u64) & ((1 << DATA_SIZE_BITS) - 1)) << 1;
        res |= (checksum & ((1 << DATA_CHECKSUM_BITS) - 1)) << (DATA_SIZE_BITS + 1);

        Ok(InstanceVersion(res))
    }

    /// Get data instance `idx` (0 or 1)
    #[inline]
    pub(crate) fn idx(&self) -> usize {
        self.0 as usize & 1
    }

    /// Get data instance `size`
    #[inline]
    pub(crate) fn size(&self) -> usize {
        (self.0 as usize >> 1) & ((1 << DATA_SIZE_BITS) - 1)
    }

    /// Get data instance `checksum`
    #[cfg(test)]
    pub(crate) fn checksum(&self) -> u64 {
        self.0 >> (DATA_SIZE_BITS + 1)
    }

    /// Get data instance `path`
    #[inline]
    pub(crate) fn path(&self, path_prefix: &OsStr) -> OsString {
        let mut path = path_prefix.to_os_string();
        path.push(format!("_data_{}", self.idx()));
        path
    }
}

impl TryFrom<u64> for InstanceVersion {
    type Error = SynchronizerError;

    /// Convert from `u64` to `InstanceVersion`
    #[inline]
    fn try_from(v: u64) -> Result<InstanceVersion, Self::Error> {
        if v == 0 {
            Err(UninitializedState)
        } else {
            Ok(InstanceVersion(v))
        }
    }
}

impl From<InstanceVersion> for u64 {
    /// Convert from `InstanceVersion` to `u64`
    #[inline]
    fn from(v: InstanceVersion) -> Self {
        v.0
    }
}

#[cfg(test)]
mod tests {
    use crate::instance::*;
    use proptest::prelude::*;

    proptest! {
        #[test]
        fn test_new(idx in 0..2usize, size in 0..1usize << DATA_SIZE_BITS, checksum in 0..u64::MAX) {
            let v = InstanceVersion::new(idx, size, checksum).unwrap();

            assert_eq!(idx, v.idx());
            assert_eq!(size, v.size());
            assert_eq!(checksum & ((1 << DATA_CHECKSUM_BITS) - 1), v.checksum());
        }
    }
}

